#define PI 3.14159265359
#define segments 5.
mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle),
                sin(_angle),cos(_angle));
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uvog = fragCoord/iResolution.xy;



    float phase = iTime*0.1;
    //polar coordinates
    vec2 uvt = uvog-vec2(0.5);
    float angle = (atan(uvt.y,uvt.x));
    float radius = (length(uvt));



    float segmentAngle = (PI*2.) / segments; //Angle of each segment
    angle -= segmentAngle * floor(angle / segmentAngle);
    angle = min(angle, segmentAngle - angle);   


    vec2 polaruv = vec2(cos(angle+phase), sin(angle+phase)) * radius + 0.5;//convert to cartesian coordinates
    //polaruv = max(min(polaruv, 2.0 - polaruv), -polaruv);  

    vec4 colt = texture(iChannel0,polaruv);
    // Output to screen
    fragColor = vec4(colt);
}
